INSERT INTO public.laboratories (id,title,slug,description,category,image,difficulty,status,instructor,requirements,duration,"order","createdAt","updatedAt") VALUES ('lab_mecanica-clasica','Mecánica Clásica','mecanica-clasica','Estudia las leyes del movimiento de Newton, cinemática de partículas, dinámica de sistemas y conservación de energía. Incluye experimentos de caída libre, péndulos y planos inclinados.','FISICA','https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=1200&q=80','INTERMEDIO','PUBLISHED','Dr. Roberto Silva','Álgebra elemental
Trigonometría básica
Conceptos de vectores',120,0,now(),now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_mecanica-clasica_pendulum', lab.id, 'Péndulo Simple', 'pendulum', 'Estudia el movimiento armónico simple de un péndulo y determina g.', 'FISICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'BASICO', 30, 0, 'Ajusta la longitud, el ángulo inicial, la gravedad y el amortiguamiento.
Pulsa Iniciar y observa la gráfica del ángulo en el tiempo.
Tras 10 oscilaciones completas la simulación se detiene y muestra el período medido.', 'T = 2π·√(L / g)
θ'''' = −(g/L)·sin θ − b·θ''', 'Un péndulo simple es una masa puntual suspendida de un hilo inextensible. Para ángulos pequeños su movimiento es armónico simple.
El período no depende de la masa ni (casi) de la amplitud: solo de la longitud del hilo y de la gravedad.
El amortiguamiento representa la fricción con el aire: la amplitud decae exponencialmente.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'mecanica-clasica' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_mecanica-clasica_projectile-motion', lab.id, 'Movimiento Parabólico', 'projectile-motion', 'Analiza el movimiento de proyectiles bajo gravedad.', 'FISICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 45, 1, 'Elige velocidad inicial, ángulo y altura de lanzamiento.
Pulsa Iniciar: la simulación se detiene sola cuando el proyectil toca el suelo.
Compara el alcance medido con el teórico en el resumen.', 'x = v₀·cos θ·t
y = h₀ + v₀·sin θ·t − ½·g·t²
R = v₀²·sin(2θ) / g  (h₀ = 0)', 'Sin resistencia del aire, el movimiento horizontal es uniforme y el vertical es uniformemente acelerado.
La trayectoria resultante es una parábola. Desde el suelo, el alcance máximo se logra con 45°.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'mecanica-clasica' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_mecanica-clasica_newtons-laws', lab.id, 'Leyes de Newton', 'newtons-laws', 'Aplica las tres leyes de Newton a diferentes escenarios.', 'FISICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 50, 2, 'Ajusta fuerza, masa y coeficiente de fricción.
Pulsa Iniciar: el bloque recorre una pista de 30 m.
Compara la aceleración medida con la teórica.', 'F neta = F − μ·m·g
a = F neta / m
x = ½·a·t²', 'Segunda ley: la aceleración de un cuerpo es proporcional a la fuerza neta e inversamente proporcional a su masa.
La fricción cinética se opone al movimiento con una fuerza μ·m·g. Si la fuerza aplicada no supera la fricción estática, el bloque no se mueve.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'mecanica-clasica' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_mecanica-clasica_energy-conservation', lab.id, 'Conservación de Energía', 'energy-conservation', 'Estudia la transformación entre energía cinética y potencial.', 'FISICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 40, 3, 'Elige altura, masa y coeficiente de restitución.
Pulsa Iniciar y observa la gráfica de energía total: baja en escalones con cada rebote.
La simulación termina tras 8 rebotes.', 'Ep = m·g·h
Ek = ½·m·v²
h₍ₙ₊₁₎ = e²·hₙ', 'En caída libre la energía potencial se convierte en cinética. Sin pérdidas, la energía mecánica total es constante.
En cada choque con el suelo parte de la energía se disipa (calor, sonido). El coeficiente de restitución e indica qué fracción de la velocidad se conserva.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'mecanica-clasica' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.laboratories (id,title,slug,description,category,image,difficulty,status,instructor,requirements,duration,"order","createdAt","updatedAt") VALUES ('lab_quimica-general','Química General','quimica-general','Estudia las propiedades de la materia, reacciones químicas, estequiometría y tablas periódicas. Incluye laboratorio virtual de reacciones ácido-base.','QUIMICA','https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1200&q=80','BASICO','PUBLISHED','Dra. Carmen Herrera','Nomenclatura química básica
Concepto de mol
Logaritmos',90,1,now(),now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_quimica-general_chemistry-lab', lab.id, 'Laboratorio Virtual de Química', 'chemistry-lab', 'Estudia la velocidad de reacción y el efecto de la temperatura.', 'QUIMICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'BASICO', 60, 0, 'Ajusta concentración inicial, temperatura y energía de activación.
Pulsa Iniciar y observa cómo el color del vaso cambia a medida que A se convierte en B.
La simulación se detiene cuando se consume el 99 % del reactivo.', '[A] = [A]₀·e^(−k·t)
k = A·e^(−Ea / R·T)
t½ = ln 2 / k', 'En una reacción de primer orden la velocidad es proporcional a la concentración del reactivo; la concentración decae exponencialmente.
La ecuación de Arrhenius explica por qué al subir la temperatura más moléculas superan la energía de activación y la reacción es más rápida.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'quimica-general' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_quimica-general_titration', lab.id, 'Titulación Ácido-Base', 'titration', 'Realiza una titulación para determinar la concentración de una solución desconocida.', 'QUIMICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 40, 1, 'Fija la concentración y el volumen del ácido, la concentración de la base y la velocidad de goteo.
Pulsa Iniciar: la bureta añade NaOH y la gráfica muestra la curva de pH.
Observa el salto brusco de pH y el cambio de color del indicador.', 'Ca·Va = Cb·Vb (equivalencia)
pH = −log[H⁺]', 'En una titulación ácido fuerte – base fuerte, el NaOH neutraliza al HCl: H⁺ + OH⁻ → H₂O.
El punto de equivalencia (pH = 7) se alcanza cuando los moles de base igualan a los de ácido. La fenolftaleína vira a rosa por encima de pH ≈ 8,2.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'quimica-general' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_quimica-general_redox-reactions', lab.id, 'Reacciones de Oxidación-Reducción', 'redox-reactions', 'Descarga una pila de Daniell y aplica la ecuación de Nernst.', 'QUIMICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 45, 2, 'Ajusta las concentraciones iniciales y la resistencia de carga.
Pulsa Iniciar y observa el flujo de electrones y la gráfica del voltaje.
La pila se considera agotada cuando el voltaje baja de 0,9 V o [Cu²⁺] se agota.', 'Zn → Zn²⁺ + 2e⁻ / Cu²⁺ + 2e⁻ → Cu
E = E° − (0,0257/2)·ln([Zn²⁺]/[Cu²⁺])
I = E / R', 'En la pila de Daniell el zinc se oxida (ánodo) y el cobre se reduce (cátodo). Los electrones viajan por el circuito externo.
A medida que la pila se descarga, [Cu²⁺] baja y [Zn²⁺] sube, y el voltaje disminuye según Nernst.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'quimica-general' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_quimica-general_stoichiometry', lab.id, 'Estequiometría', 'stoichiometry', 'Cálculos de reacciones químicas, reactivo limitante y rendimiento.', 'QUIMICA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 45, 3, 'Elige los moles iniciales de H₂ y O₂.
Pulsa Iniciar: las moléculas reaccionan hasta que se agota el limitante.
Revisa en el resumen qué reactivo sobra y cuánto.', '2 H₂ + O₂ → 2 H₂O
n(H₂O) máx = mín(n(H₂), 2·n(O₂))', 'La ecuación balanceada 2 H₂ + O₂ → 2 H₂O indica las proporciones en moles en que reaccionan las sustancias.
El reactivo limitante se consume primero y determina la cantidad máxima de producto (rendimiento teórico).', now(), now() FROM public.laboratories lab WHERE lab.slug = 'quimica-general' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.laboratories (id,title,slug,description,category,image,difficulty,status,instructor,requirements,duration,"order","createdAt","updatedAt") VALUES ('lab_biologia-celular','Biología Celular','biologia-celular','Explora la estructura celular, organelos, mitosis y meiosis. Incluye visualización 3D de células eucariotas y procariotas.','BIOLOGIA','https://images.unsplash.com/photo-1576086213369-97a306d36557?w=1200&q=80','INTERMEDIO','PUBLISHED','Dr. Miguel Ángel Torres','Biología general
Estructura de la célula',100,2,now(),now()) ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_biologia-celular_mitosis', lab.id, 'Mitosis', 'mitosis', 'Observa en 3D las fases de la división celular.', 'BIOLOGIA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'INTERMEDIO', 50, 0, 'Ajusta el número de pares de cromosomas, la temperatura y la velocidad de observación.
Pulsa Iniciar y sigue el movimiento de los cromosomas en la célula 3D.
Al terminar la citocinesis verás el resumen con la duración de cada fase.', 'Duración relativa ≈ Interfase 30 % · Profase 20 % · Metafase 12 % · Anafase 10 % · Telofase 13 % · Citocinesis 15 %', 'La mitosis divide una célula en dos células hijas genéticamente idénticas.
Fases: profase (condensación de cromosomas), metafase (alineación en el ecuador), anafase (separación de cromátidas), telofase (nuevas envolturas nucleares) y citocinesis (división del citoplasma).
La temperatura acelera el ciclo hasta un óptimo (~37 °C); por encima, la célula se estresa y el ciclo se ralentiza.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'biologia-celular' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_biologia-celular_cell-observation', lab.id, 'Observación Celular', 'cell-observation', 'Identifica estructuras celulares al microscopio.', 'BIOLOGIA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'BASICO', 40, 1, 'Selecciona el aumento, ajusta el enfoque (óptimo cerca de 50) y la intensidad de la tinción.
Pulsa Iniciar: el microscopio recorre la muestra y cuenta las células detectadas.
Mejor enfoque y tinción = más células detectadas correctamente.', 'Aumento total = objetivo × ocular (10×)
Densidad = células contadas / área observada', 'El microscopio óptico amplía la muestra mediante el objetivo y el ocular. Un enfoque correcto es imprescindible para distinguir estructuras.
La tinción (p. ej. azul de metileno) aumenta el contraste del núcleo y la pared celular.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'biologia-celular' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
INSERT INTO public.experiments (id,"laboratoryId",title,slug,description,category,image,difficulty,duration,"order",instructions,formulas,theory,"createdAt","updatedAt") SELECT 'exp_biologia-celular_mendelian-inheritance', lab.id, 'Herencia Mendeliana', 'mendelian-inheritance', 'Predice resultados de cruzamientos monohíbridos.', 'BIOLOGIA', 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=400&q=80', 'AVANZADO', 50, 2, 'Elige el genotipo de cada progenitor (0 = AA, 1 = Aa, 2 = aa) y el número de descendientes.
Pulsa Iniciar: cada guisante aparece en 3D con su color.
Compara la proporción observada con la esperada en el resumen.', 'Aa × Aa → 1 AA : 2 Aa : 1 aa
χ² = Σ (O − E)² / E', 'Mendel demostró que cada carácter está determinado por dos alelos, uno de cada progenitor. El alelo dominante (A, amarillo) enmascara al recesivo (a, verde).
En un cruce Aa × Aa se espera una proporción fenotípica 3:1 y genotípica 1:2:1. Con pocas muestras el azar produce desviaciones.', now(), now() FROM public.laboratories lab WHERE lab.slug = 'biologia-celular' ON CONFLICT ("laboratoryId", slug) DO NOTHING;
